void AHPNativeHUD::Text(const FString& T,float X,float Y,FLinearColor C,float Scale){DrawText(T,C,X,Y,GEngine->GetSmallFont(),Scale);}
void AHPNativeHUD::Button(FName Id,const FString& Label,float X,float Y,float Width){DrawRect(FLinearColor(.06,.15,.18,.96),X,Y,Width,32);Text(Label,X+10,Y+8);AddHitBox(FVector2D(X,Y),FVector2D(Width,32),Id,true);}
void AHPNativeHUD::DrawHUD(){Super::DrawHUD();if(!Canvas)return;auto* S=AShipManager::GetShipManager(this);auto* P=Cast<AHeliopauseCharacter>(GetOwningPawn());if(!S||!P)return;const float W=Canvas->SizeX,H=Canvas->SizeY;auto* E=S->Expedition();
 if(S->bMenu){DrawRect(FLinearColor(.01,.025,.04,.95),0,0,W,H);Text(TEXT("HELIOPAUSE"),W*.15,H*.2,FLinearColor(.8,.9,.85),3);Text(TEXT("A LONG WAY HOME / SV-7 LONGHAUL"),W*.15,H*.2+65);Button(TEXT("story"),TEXT("STORY / NEW OR CONTINUE"),W*.15,H*.4,330);Button(TEXT("free"),TEXT("FREE EXPLORATION"),W*.15,H*.4+45,330);Text(TEXT("WASD move | mouse look | E interact | T tablet | V cameras (orbit: mouse, PgUp/PgDn zoom)"),W*.15,H*.7);Text(TEXT("Generated EVA recordings + subtitles. All gameplay runs locally."),W*.15,H*.7+25);return;}
 if(S->IsInCutscene()){DrawRect(FLinearColor::Black,0,0,W,H*.1);DrawRect(FLinearColor::Black,0,H*.84,W,H*.16);Text(TEXT("SPACE — SKIP SCENE"),W-220,H*.9);}else{Text(TEXT("HELIOPAUSE / SV-7 LONGHAUL"),24,20,FLinearColor(.4,.8,.75),1.3f);Text(S->GetObjectiveText().ToString(),24,50);Text(FString::Printf(TEXT("ALT %.1f KM   VEL %.0f M/S   HEAT %.0f%%"),S->Altitude,S->Velocity,S->Heat*100),24,75);Text(P->GetCurrentPrompt().ToString(),W*.38,H*.8);Text(TEXT("T tablet | E interact | V cameras | F flashlight | Shift run | C crouch"),24,H-35);}
 if(auto* Voice=GetWorld()->GetSubsystem<UEVASubsystem>())if(Voice->SubtitleRemaining>0){const FString L=Voice->CurrentSubtitle.ToString();DrawRect(FLinearColor(0,.015,.025,.9),W*.08,H*.72,W*.84,65);for(int Start=0,Line=0;Start<L.Len();Start+=110,++Line)Text(L.Mid(Start,110),W*.1,H*.73+Line*18,FLinearColor(.95,.95,.85));}
 if(S->StaticTime>0){DrawRect(FLinearColor(.2,.3,.3,.9),0,0,W,H);Text(TEXT("SIGNAL LOST / RETURNING TO CREW"),W*.3,H*.5);}
 if(!P->bFallbackTablet||S->IsInCutscene()||!E)return;const float X=W*.45,Y=100;DrawRect(FLinearColor(.015,.04,.055,.98),X-15,Y-15,W*.55-5,H-150);for(int I=0;I<5;++I)Button(FName(*FString::Printf(TEXT("tab%d"),I)),TArray<FString>{TEXT("FLIGHT"),TEXT("SYSTEMS"),TEXT("DRONES"),TEXT("EXPEDITION"),TEXT("HABITAT")}[I],X+I*88,Y,84);float Row=Y+50;
 if(Tab==0){if(S->bLanded){Button(TEXT("launchsurface"),TEXT("RELEASE LANDING CLAMPS / MANUAL LAUNCH"),X,Row,360);Row+=42;}Button(TEXT("pilot"),S->bPilot?TEXT("LEAVE PILOT SEAT"):TEXT("TAKE PILOT SEAT"),X,Row,280);Row+=42;Button(TEXT("entry"),TEXT("ENTRY SURVEY / 60 KM"),X,Row,280);Row+=42;Button(TEXT("climb"),TEXT("CLIMB TO ORBIT / 400 KM"),X,Row,280);Row+=42;Button(TEXT("hold"),TEXT("HOLD ALTITUDE"),X,Row,280);Row+=42;Button(TEXT("manual"),TEXT("MANUAL / DISENGAGE AUTOPILOT"),X,Row,280);Row+=40;Text(TEXT("W/S thrust AD yaw RF pitch QE roll Shift/Ctrl vertical B brake"),X,Row);}
 if(Tab==1){const auto Rooms=S->GetRoomNames();for(int I=0;I<Rooms.Num();++I){Button(FName(*FString::Printf(TEXT("light%d"),I)),Rooms[I].ToString()+(S->IsRoomOn(Rooms[I])?TEXT(" / LIGHT ON"):TEXT(" / LIGHT OFF")),X,Row,220);Button(FName(*FString::Printf(TEXT("repair%d"),I)),TEXT("DISPATCH"),X+230,Row,95);Row+=38;Text(FString::Printf(TEXT("PRESSURE %.0f%% / %.0f C"),S->Pressure[I]*100,S->Temperature[I]),X,Row);Row+=24;}Button(TEXT("shade"),S->bThermalLock?TEXT("CURTAIN / THERMAL LOCK"):TEXT("TOGGLE QUARTERS CURTAIN"),X,Row,325);Button(TEXT("breath"),P->bBreathingEnabled?TEXT("BREATHING FOLEY ON"):TEXT("BREATHING FOLEY OFF"),X,Row+40,325);}
 if(Tab==2){for(int I=0;I<3;++I){Button(FName(*FString::Printf(TEXT("drone%d"),I)),FString::Printf(TEXT("%s / %.0f%% / TAKE CONTROL"),*TArray<FString>{TEXT("KESTREL"),TEXT("MENDER"),TEXT("FINCH")}[I],S->DroneHealth[I]),X,Row,340);Row+=45;}Button(TEXT("release"),TEXT("RELEASE DRONE LINK"),X,Row,340);}
 if(Tab==4){Text(TEXT("STOP SHIP / TRANSITION DOORS LOCK / OCCUPANCY GUARD"),X,Row);Row+=30;for(int I=0;I<S->Habitats.Num();++I){const auto& H=S->Habitats[I];const bool Deployed=H.State.phase==HPHabitat::Phase::Deployed;Button(FName(*FString::Printf(TEXT("habitat%d"),I)),H.Name.ToString()+(Deployed?TEXT(" / COMPACT"):TEXT(" / DEPLOY")),X,Row,340);Row+=36;Text(H.Interior?TEXT("INTERIOR LOADED"):TEXT("INTERIOR UNLOADED"),X,Row);Row+=24;}}
 if(Tab==3){Text(UTF8_TO_TCHAR(E->State.message.c_str()),X,Row);Row+=28;const auto& Site=HelioExplore::Sites[E->State.target];Button(TEXT("target"),FString::Printf(TEXT("TARGET: %s / %.1f KM [NEXT]"),UTF8_TO_TCHAR(Site.name),E->State.distance(E->State.target)),X,Row,380);Row+=45;const TArray<FString> Ids={TEXT("undock"),TEXT("navigate"),TEXT("brake"),TEXT("scan"),TEXT("recover"),TEXT("dock"),TEXT("board"),TEXT("return"),TEXT("sell"),TEXT("engine"),TEXT("sensor"),TEXT("save")};for(int I=0;I<Ids.Num();++I)Button(FName(*Ids[I]),Ids[I].ToUpper(),X+(I%3)*125,Row+(I/3)*40,118);Row+=175;Text(FString::Printf(TEXT("CREDITS %d | UNARCHIVED %d | DRIVE %d SCANNER %d"),E->State.credits,E->State.pending(),E->State.engine,E->State.sensor),X,Row);}
}
void AHPNativeHUD::NotifyHitBoxClick(FName Id){Super::NotifyHitBoxClick(Id);auto* S=AShipManager::GetShipManager(this);auto* P=Cast<AHeliopauseCharacter>(GetOwningPawn());if(!S||!P||S->IsInCutscene())return;const FString K=Id.ToString();if(K==TEXT("story")||K==TEXT("free")){S->BeginGame(K==TEXT("story"));return;}if(!P->IsTabletOpen())return;
 if(K.StartsWith(TEXT("tab"))){Tab=FCString::Atoi(*K.RightChop(3));return;}if(K==TEXT("breath")){P->bBreathingEnabled=!P->bBreathingEnabled;return;}if(K==TEXT("launchsurface")){S->LaunchFromSurface();return;}if(K==TEXT("pilot")){S->TogglePilot();return;}if(K==TEXT("manual")){S->SetAutopilot(EHPAutopilot::Manual);if(auto* E=S->Expedition())E->State.autopilot=false;return;}if(K==TEXT("entry")){S->SetAutopilot(EHPAutopilot::EntrySurvey);return;}if(K==TEXT("climb")){S->SetAutopilot(EHPAutopilot::ClimbToOrbit);return;}if(K==TEXT("hold")){S->SetAutopilot(EHPAutopilot::Hold);return;}
 if(K.StartsWith(TEXT("habitat"))){const int I=FCString::Atoi(*K.RightChop(7));if(S->Habitats.IsValidIndex(I))S->RequestHabitat(I,S->Habitats[I].State.phase!=HPHabitat::Phase::Deployed);return;}if(K.StartsWith(TEXT("light"))){const int I=FCString::Atoi(*K.RightChop(5));const auto Rooms=S->GetRoomNames();if(Rooms.IsValidIndex(I))S->SetRoomLights(Rooms[I],!S->IsRoomOn(Rooms[I]));return;}if(K.StartsWith(TEXT("repair"))){S->RequestRepair(FCString::Atoi(*K.RightChop(6)));return;}if(K==TEXT("shade")){const auto Windows=S->GetWindows();if(!Windows.IsEmpty()&&Windows[0])S->SetWindowOpen(Windows[0]->WindowName,!Windows[0]->IsOpen());return;}if(K.StartsWith(TEXT("drone"))){S->ControlDrone(FCString::Atoi(*K.RightChop(5)));return;}if(K==TEXT("release")){S->ControlledDrone=-1;S->SetCamera(0);return;}
 auto* E=S->Expedition();if(!E)return;if(K==TEXT("save")){E->Save();return;}if(S->IsStory()&&S->GetStoryStep()<8)return;if(K==TEXT("target")){E->State.select((E->State.target+1)%HelioExplore::Sites.size());return;}if(K==TEXT("board")){S->BoardStation();return;}if(K==TEXT("return")){S->ReturnToShip();return;}
 using C=HelioExplore::Command;const TMap<FString,C> Commands={{TEXT("undock"),C::Undock},{TEXT("navigate"),C::Navigate},{TEXT("brake"),C::Brake},{TEXT("scan"),C::Scan},{TEXT("recover"),C::Recover},{TEXT("dock"),C::Dock},{TEXT("sell"),C::Sell},{TEXT("engine"),C::Engine},{TEXT("sensor"),C::Sensor}};if(const C* Cmd=Commands.Find(K)){const bool Exchange=*Cmd==C::Sell||*Cmd==C::Engine||*Cmd==C::Sensor;if(Exchange&&!S->AtExchange()){E->State.message="Walk to the station exchange terminal first.";return;}if(!Exchange&&!S->bPilot){E->State.message="Take the pilot seat first.";return;}E->Command(*Cmd);}
}
